PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_physiology_07', 'deck_sys_topic_physiology', 'State three functions of the liver.', 'Any three of: production of bile for fat emulsification; deamination of excess amino acids (forming urea); detoxification of drugs and alcohol; storage of glucose as glycogen; breakdown of worn-out red blood cells; heat production.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_physiology_08', 'deck_sys_topic_physiology', 'How does the body respond when the core temperature falls?', 'Arterioles near the skin constrict (vasoconstriction) to reduce heat loss, shivering generates heat through rapid muscle contraction, sweating stops, and hairs are raised to trap an insulating layer of air.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_physiology_09', 'deck_sys_topic_physiology', 'Summarise the sliding filament theory of muscle contraction.', 'Using energy from ATP, myosin heads attach to actin filaments and pull them towards the centre of the sarcomere, so the actin and myosin filaments slide past each other and the muscle fibre shortens.', NULL, NULL, 4);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_b002_physiology_10', 'deck_sys_topic_physiology', 'Compare inhalation with exhalation in humans.', 'Inhalation: the diaphragm contracts and flattens and the external intercostal muscles raise the ribs, increasing thoracic volume and lowering pressure so air flows in. Exhalation is largely passive: the muscles relax, volume falls, pressure rises and air flows out.', NULL, NULL, 3);
